#!/usr/bin/env python
# -*- coding: utf-8 -*-

B = [list(input()) for i in range(0,8)]
A_min = 9
B_min = 9

for i in range(8):
    A_tmp = False
    B_tmp = False
    for j in range(8):
        if B[j][i] == 'W':
            if B_tmp is False:
                A_tmp = j
            else:
                break
        elif B[j][i] == 'B':
            B_tmp = j
    else:
        A_min = min(A_min, A_tmp) if A_tmp is not False else A_min
        B_min = min(B_min, 7 - B_tmp) if B_tmp is not False else B_min
if A_min < B_min:
    print('A')
else:
    print('B')

